  "provider": {},
  "securitySchemes": {
    "mtls": {
      "type": "mutualTLS",
      "description": "使用平台认可的 AIC clientAuth 证书连接平台 AMQPS 与群组授权服务。"
    }
  },
  "endPoints": [],
  "capabilities": {
    "streaming": false,
    "notification": false,
    "messageQueue": [
      "amqp:0.9.1"
    ]
  },
  "defaultInputModes": [
    "application/json",
    "text/plain"
  ],
  "defaultOutputModes": [
    "application/json"
  ],
  "skills": [
    {
      "id": "interop.probe.coordinate",
      "name": "只读互联任务协调",
      "description": "主动发起受控的双智能体通信测试，生成随机 nonce，验证 read-only-probe 返回的 nonce、Partner AIC、业务修改数为零以及任务完成状态。不向其他智能体提供可调用的入站接口。",
      "version": "0.1.0",
      "tags": [
        "互联验证",
        "AIP",
        "协调者",
        "只读",
        "nonce"
      ],
      "inputModes": [
        "application/json",
        "text/plain"
      ],
      "outputModes": [
        "application/json"
      ]
    }
  ]
